// 1. Input Validation
if (!isfinite(gb_config.stationary_limit_rad_s) || gb_config.stationary_limit_rad_s < 0.0 ||
    !isfinite(gb_config.max_sample_delta_rad_s) || gb_config.max_sample_delta_rad_s < 0.0 ||
    !isfinite(gb_config.max_stddev_rad_s) || gb_config.max_stddev_rad_s < 0.0 ||
    gb_config.required_samples < 3 || gb_config.required_samples > 100 ||
    gb_config.max_rejected_windows < 1 || gb_config.max_rejected_windows > 20 ||
    !isfinite(gb_config.drift_limit_rad_s) || gb_config.drift_limit_rad_s < 0.0 ||
    gb_config.drift_confirm_samples < 1 || gb_config.drift_confirm_samples > 20) {

    gb_state.mode = GB_FAULT;
    gb_output.mode = GB_FAULT;
    gb_output.count = 0;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s.x = 0.0;
    gb_output.bias_rad_s.y = 0.0;
    gb_output.bias_rad_s.z = 0.0;
    gb_output.variance_rad_s2.x = 0.0;
    gb_output.variance_rad_s2.y = 0.0;
    gb_output.variance_rad_s2.z = 0.0;
    return;
}

// 2. Disable Handling
if (!gb_input.enable) {
    gb_state.mode = GB_OFF;
    gb_state.count = 0;
    gb_state.has_previous = 0;
    gb_state.mean_rad_s.x = 0.0;
    gb_state.mean_rad_s.y = 0.0;
    gb_state.mean_rad_s.z = 0.0;
    gb_state.m2_rad_s2.x = 0.0;
    gb_state.m2_rad_s2.y = 0.0;
    gb_state.m2_rad_s2.z = 0.0;
    gb_state.drift_count = 0;

    gb_output.mode = GB_COLLECT;
    gb_output.count = 0;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s.x = 0.0;
    gb_output.bias_rad_s.y = 0.0;
    gb_output.bias_rad_s.z = 0.0;
    gb_output.variance_rad_s2.x = 0.0;
    gb_output.variance_rad_s2.y = 0.0;
    gb_output.variance_rad_s2.z = 0.0;
    return;
}

// 4. FAULT Mode Handling (Check before READY to ensure Fault overrides)
if (gb_state.mode == GB_FAULT) {
    gb_output.mode = GB_FAULT;
    gb_output.count = gb_state.count;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s.x = 0.0;
    gb_output.bias_rad_s.y = 0.0;
    gb_output.bias_rad_s.z = 0.0;
    gb_output.variance_rad_s2.x = 0.0;
    gb_output.variance_rad_s2.y = 0.0;
    gb_output.variance_rad_s2.z = 0.0;
    return;
}

// 3. READY Mode Drift Detection
if (gb_state.mode == GB_READY) {
    adcs_vec3_t diff = adcs_vec3_sub(gb_input.rate_rad_s, &gb_state.bias_rad_s);
    double dist = adcs_vec3_norm(&diff);

    if (dist > gb_config.drift_limit_rad_s) {
        gb_state.drift_count++;
        if (gb_state.drift_count >= gb_config.drift_confirm_samples) {
            // Discard calibration, restart collection
            gb_state.mode = GB_COLLECT;
            gb_state.count = 0;
            gb_state.has_previous = 0;
            gb_state.mean_rad_s.x = 0.0;
            gb_state.mean_rad_s.y = 0.0;
            gb_state.mean_rad_s.z = 0.0;
            gb_state.m2_rad_s2.x = 0.0;
            gb_state.m2_rad_s2.y = 0.0;
            gb_state.m2_rad_s2.z = 0.0;
            // Fall through to COLLECT logic to process this sample as first in new window
        } else {
            // Not enough drift confirmations, stay in READY
            gb_output.mode = GB_READY;
            gb_output.count = gb_state.count;
            gb_output.rejected_windows = gb_state.rejected_windows;
            gb_output.rejection = GB_REJECT_NONE;
            gb_output.bias_rad_s = gb_state.bias_rad_s;
            gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
            return;
        }
    } else {
        // Within limit, reset counter, stay in READY
        gb_state.drift_count = 0;
        gb_output.mode = GB_READY;
        gb_output.count = gb_state.count;
        gb_output.rejected_windows = gb_state.rejected_windows;
        gb_output.rejection = GB_REJECT_NONE;
        gb_output.bias_rad_s = gb_state.bias_rad_s;
        gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
        return;
    }
}

// At this point, we are in COLLECT mode (either initially or after READY reset)

// 5. Sample Admission Check
gb_rejection_t current_rejection = GB_REJECT_NONE;
int sample_accepted = 1;

double rate_norm = adcs_vec3_norm(gb_input.rate_rad_s);
if (rate_norm > gb_config.stationary_limit_rad_s) {
    sample_accepted = 0;
    current_rejection = GB_REJECT_RATE;
} else if (gb_state.has_previous) {
    adcs_vec3_t delta = adcs_vec3_sub(gb_input.rate_rad_s, &gb_state.previous_rate_rad_s);
    double delta_norm = adcs_vec3_norm(&delta);
    if (delta_norm > gb_config.max_sample_delta_rad_s) {
        sample_accepted = 0;
        current_rejection = GB_REJECT_STEP;
    }
}

if (!sample_accepted) {
    // Clear window and increment rejected windows
    gb_state.count = 0;
    gb_state.has_previous = 0;
    gb_state.mean_rad_s.x = 0.0;
    gb_state.mean_rad_s.y = 0.0;
    gb_state.mean_rad_s.z = 0.0;
    gb_state.m2_rad_s2.x = 0.0;
    gb_state.m2_rad_s2.y = 0.0;
    gb_state.m2_rad_s2.z = 0.0;

    gb_state.rejected_windows++;
    if (gb_state.rejected_windows >= gb_config.max_rejected_windows) {
        gb_state.mode = GB_FAULT;
    }

    gb_output.mode = GB_COLLECT;
    gb_output.count = 0;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = current_rejection;
    gb_output.bias_rad_s.x = 0.0;
    gb_output.bias_rad_s.y = 0.0;
    gb_output.bias_rad_s.z = 0.0;
    gb_output.variance_rad_s2.x = 0.0;
    gb_output.variance_rad_s2.y = 0.0;
    gb_output.variance_rad_s2.z = 0.0;
    return;
}

// 6. Welford Update
size_t n = gb_state.count + 1;
adcs_vec3_t prev_mean = gb_state.mean_rad_s;
adcs_vec3_t new_mean = adcs_vec3_scale(&prev_mean, 1.0 - 1.0/n);
adcs_vec3_t diff_from_old_mean = adcs_vec3_sub(gb_input.rate_rad_s, &prev_mean);
adcs_vec3_t term = adcs_vec3_scale(&diff_from_old_mean, 1.0/n);
new_mean = adcs_vec3_add(&new_mean, &term);

adcs_vec3_t diff_from_new_mean = adcs_vec3_sub(gb_input.rate_rad_s, &new_mean);

gb_state.mean_rad_s = new_mean;

// M2 update: M2_new = M2_old + (x - mean_old) * (x - mean_new)
gb_state.m2_rad_s2.x += diff_from_old_mean.x * diff_from_new_mean.x;
gb_state.m2_rad_s2.y += diff_from_old_mean.y * diff_from_new_mean.y;
gb_state.m2_rad_s2.z += diff_from_old_mean.z * diff_from_new_mean.z;

gb_state.count = n;
gb_state.has_previous = 1;
gb_state.previous_rate_rad_s = *gb_input.rate_rad_s;

// 7. Variance Check and Ready Transition
if (gb_state.count == gb_config.required_samples) {
    double var_x = gb_state.m2_rad_s2.x / gb_state.count;
    double var_y = gb_state.m2_rad_s2.y / gb_state.count;
    double var_z = gb_state.m2_rad_s2.z / gb_state.count;

    if (var_x <= gb_config.max_stddev_rad_s * gb_config.max_stddev_rad_s &&
        var_y <= gb_config.max_stddev_rad_s * gb_config.max_stddev_rad_s &&
        var_z <= gb_config.max_stddev_rad_s * gb_config.max_stddev_rad_s) {

        gb_state.mode = GB_READY;
        gb_state.bias_rad_s = gb_state.mean_rad_s;
        gb_state.variance_rad_s2.x = var_x;
        gb_state.variance_rad_s2.y = var_y;
        gb_state.variance_rad_s2.z = var_z;

        gb_output.mode = GB_READY;
        gb_output.count = gb_state.count;
        gb_output.rejected_windows = gb_state.rejected_windows;
        gb_output.rejection = GB_REJECT_NONE;
        gb_output.bias_rad_s = gb_state.bias_rad_s;
        gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
        return;
    } else {
        // Noisy window rejected
        gb_state.count = 0;
        gb_state.has_previous = 0;
        gb_state.mean_rad_s.x = 0.0;
        gb_state.mean_rad_s.y = 0.0;
        gb_state.mean_rad_s.z = 0.0;
        gb_state.m2_rad_s2.x = 0.0;
        gb_state.m2_rad_s2.y = 0.0;
        gb_state.m2_rad_s2.z = 0.0;

        gb_state.rejected_windows++;
        if (gb_state.rejected_windows >= gb_config.max_rejected_windows) {
            gb_state.mode = GB_FAULT;
        }

        gb_output.mode = GB_COLLECT;
        gb_output.count = 0;
        gb_output.rejected_windows = gb_state.rejected_windows;
        gb_output.rejection = GB_REJECT_VARIANCE;
        gb_output.bias_rad_s.x = 0.0;
        gb_output.bias_rad_s.y = 0.0;
        gb_output.bias_rad_s.z = 0.0;
        gb_output.variance_rad_s2.x = 0.0;
        gb_output.variance_rad_s2.y = 0.0;
        gb_output.variance_rad_s2.z = 0.0;
        return;
    }
}

// 8. Output Construction for partial collection
gb_output.mode = GB_COLLECT;
gb_output.count = gb_state.count;
gb_output.rejected_windows = gb_state.rejected_windows;
gb_output.rejection = GB_REJECT_NONE;
gb_output.bias_rad_s.x = 0.0;
gb_output.bias_rad_s.y = 0.0;
gb_output.bias_rad_s.z = 0.0;

if (gb_state.count > 0) {
     gb_output.variance_rad_s2.x = gb_state.m2_rad_s2.x / gb_state.count;
     gb_output.variance_rad_s2.y = gb_state.m2_rad_s2.y / gb_state.count;
     gb_output.variance_rad_s2.z = gb_state.m2_rad_s2.z / gb_state.count;
} else {
     gb_output.variance_rad_s2.x = 0.0;
     gb_output.variance_rad_s2.y = 0.0;
     gb_output.variance_rad_s2.z = 0.0;
}

