// At this point, we are in COLLECT mode (either initially or after READY reset)

// 5. Sample Admission Check
gb_rejection_t current_rejection = GB_REJECT_NONE;
int sample_accepted = 1;

double rate_norm = adcs_vec3_norm(gb_input.rate_rad_s);
if (rate_norm > gb_config.stationary_limit_rad_s) {
    sample_accepted = 0;
    current_rejection = GB_REJECT_RATE;
} else if (gb_state.has_previous) {
    adcs_vec3_t delta = adcs_vec3_sub(gb_input.rate_rad_s, &gb_state.previous_rate_rad_s);
    double delta_norm = adcs_vec3_norm(&delta);
    if (delta_norm > gb_config.max_sample_delta_rad_s) {
        sample_accepted = 0;
        current_rejection = GB_REJECT_STEP;
    }
} else {
