// 6. Welford Update
size_t n = gb_state.count + 1;
adcs_vec3_t prev_mean = gb_state.mean_rad_s;
adcs_vec3_t new_mean = adcs_vec3_scale(&prev_mean, 1.0 - 1.0/n);
adcs_vec3_t diff_from_old_mean = adcs_vec3_sub(gb_input.rate_rad_s, &prev_mean);
adcs_vec3_t term = adcs_vec3_scale(&diff_from_old_mean, 1.0/n);
new_mean = adcs_vec3_add(&new_mean, &term);

adcs_vec3_t diff_from_new_mean = adcs_vec3_sub(gb_input.rate_rad_s, &new_mean);

gb_state.mean_rad_s = new_mean;

// M2 update: M2_new = M2_old + (x - mean_old) * (x - mean_new)
gb_state.m2_rad_s2.x += diff_from_old_mean.x * diff_from_new_mean.x;
gb_state.m2_rad_s2.y += diff_from_old_mean.y * diff_from_new_mean.y;
gb_state.m2_rad_s2.z += diff_from_old_mean.z * diff_from_new_mean.z;

gb_state.count = n;
gb_state.has_previous = 1;
gb_state.previous_rate_rad_s = *gb_input.rate_rad_s;

