            gb_output.bias_rad_s.y = 0.0;
            gb_output.bias_rad_s.z = 0.0;
            gb_output.variance_rad_s2.x = 0.0;
            gb_output.variance_rad_s2.y = 0.0;
            gb_output.variance_rad_s2.z = 0.0;
            return;
        }
        // Rejected window publishes zero statistics
        gb_output.mode = GB_COLLECT;
        gb_output.count = 0;
        gb_output.rejected_windows = gb_state.rejected_windows;
        gb_output.bias_rad_s.x = 0.0;
        gb_output.bias_rad_s.y = 0.0;
        gb_output.bias_rad_s.z = 0.0;
        gb_output.variance_rad_s2.x = 0.0;
        gb_output.variance_rad_s2.y = 0.0;
        gb_output.variance_rad_s2.z = 0.0;
        return;
    }

    // Welford update
    gb_state.count++;
    size_t n = (size_t)gb_state.count;

    adcs_vec3_t current_mean = gb_state.mean_rad_s;
    adcs_vec3_t diff1 = adcs_vec3_sub(gb_input.rate_rad_s, &current_mean);
    adcs_vec3_t scale_diff1 = adcs_vec3_scale(&diff1, 1.0 / n);
    adcs_vec3_t new_mean = adcs_vec3_add(&current_mean, &scale_diff1);

    gb_state.mean_rad_s = new_mean;

    adcs_vec3_t diff2 = adcs_vec3_sub(gb_input.rate_rad_s, &new_mean);

    gb_state.m2_rad_s2.x += diff1.x * diff2.x;
    gb_state.m2_rad_s2.y += diff1.y * diff2.y;
    gb_state.m2_rad_s2.z += diff1.z * diff2.z;

    gb_state.previous_rate_rad_s = *gb_input.rate_rad_s;
    gb_state.has_previous = 1;
}

