            // Discard calibration, restart collection
            gb_state.mode = GB_COLLECT;
            gb_state.count = 0;
            gb_state.has_previous = 0;
            gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
            gb_state.m2_rad_s2.x = 0.0; gb_state.m2_rad_s2.y = 0.0; gb_state.m2_rad_s2.z = 0.0;
            // rejected_windows NOT incremented by drift
            // Do not return here, fall through to process current sample as first of new window
        }
    }
}

// Initialize output defaults for this step
gb_output.mode = gb_state.mode;
gb_output.count = gb_state.count;
gb_output.rejected_windows = gb_state.rejected_windows;
gb_output.rejection = GB_REJECT_NONE;

// Bias is zero in every mode except READY
if (gb_state.mode != GB_READY) {
    gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
} else {
    gb_output.bias_rad_s = gb_state.bias_rad_s;
}

// 4. Sample Admission Check
const adcs_vec3_t *sample = gb_input.rate_rad_s;
double norm = adcs_vec3_norm(sample);

// Check Rate Limit
if (norm > gb_config.stationary_limit_rad_s) {
    gb_state.count = 0;
    gb_state.has_previous = 0;
    gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
    gb_state.m2_rad_s2.x = 0.0; gb_state.m2_rad_s2.y = 0.0; gb_state.m2_rad_s2.z = 0.0;
    gb_state.rejected_windows++;
    gb_output.rejection = GB_REJECT_RATE;
    gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;

    if (gb_state.rejected_windows >= gb_config.max_rejected_windows) {
        gb_state.mode = GB_FAULT;
        gb_output.mode = GB_FAULT;
    }
    return;
}

// Check Delta Limit
if (gb_state.has_previous) {
    adcs_vec3_t delta = adcs_vec3_sub(sample, &gb_state.previous_rate_rad_s);
    double delta_norm = adcs_vec3_norm(&delta);
    if (delta_norm > gb_config.max_sample_delta_rad_s) {
        gb_state.count = 0;
        gb_state.has_previous = 0;
        gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
        gb_state.m2_rad_s2.x = 0.0; gb_state.m2_rad_s2.y = 0.0; gb_state.m2_rad_s2.z = 0.0;
        gb_state.rejected_windows++;
        gb_output.rejection = GB_REJECT_STEP;
        gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;

        if (gb_state.rejected_windows >= gb_config.max_rejected_windows) {
            gb_state.mode = GB_FAULT;
            gb_output.mode = GB_FAULT;
        }
        return;
    }
}

// 5. Welford Update
gb_state.has_previous = 1;
gb_state.previous_rate_rad_s = *sample;
gb_state.count++;

double n = (double)gb_state.count;
adcs_vec3_t delta_mean = adcs_vec3_scale(sample, 1.0 / n);
adcs_vec3_t new_mean = adcs_vec3_add(&gb_state.mean_rad_s, &delta_mean);

// M2 update per axis
for (int i = 0; i < 3; i++) {
    double x = (i == 0) ? sample->x : ((i == 1) ? sample->y : sample->z);
    double old_mean = (i == 0) ? gb_state.mean_rad_s.x : ((i == 1) ? gb_state.mean_rad_s.y : gb_state.mean_rad_s.z);
    double new_mean_val = (i == 0) ? new_mean.x : ((i == 1) ? new_mean.y : new_mean.z);
    double old_m2 = (i == 0) ? gb_state.m2_rad_s2.x : ((i == 1) ? gb_state.m2_rad_s2.y : gb_state.m2_rad_s2.z);

    double term = (x - old_mean) * (x - new_mean_val);
    double new_m2 = old_m2 + term;

    if (i == 0) gb_state.m2_rad_s2.x = new_m2;
    if (i == 1) gb_state.m2_rad_s2.y = new_m2;
    if (i == 2) gb_state.m2_rad_s2.z = new_m2;
}

gb_state.mean_rad_s = new_mean;

// 6. Window Completion Check
if (gb_state.count == gb_config.required_samples) {
    // Check Population Variance
    double max_var_sq = gb_config.max_stddev_rad_s * gb_config.max_stddev_rad_s;
    int all_ok = 1;

    if (gb_state.m2_rad_s2.x / gb_state.count > max_var_sq) all_ok = 0;
    if (gb_state.m2_rad_s2.y / gb_state.count > max_var_sq) all_ok = 0;
    if (gb_state.m2_rad_s2.z / gb_state.count > max_var_sq) all_ok = 0;

    if (!all_ok) {
        gb_state.count = 0;
        gb_state.has_previous = 0;
        gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
        gb_state.m2_rad_s2.x = 0.0; gb_state.m2_rad_s2.y = 0.0; gb_state.m2_rad_s2.z = 0.0;
        gb_state.rejected_windows++;
        gb_output.rejection = GB_REJECT_VARIANCE;
        gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;

        if (gb_state.rejected_windows >= gb_config.max_rejected_windows) {
            gb_state.mode = GB_FAULT;
            gb_output.mode = GB_FAULT;
        }
        return;
    }

    // Accept Bias
    gb_state.bias_rad_s = gb_state.mean_rad_s;
    gb_state.variance_rad_s2.x = gb_state.m2_rad_s2.x / gb_state.count;
    gb_state.variance_rad_s2.y = gb_state.m2_rad_s2.y / gb_state.count;
    gb_state.variance_rad_s2.z = gb_state.m2_rad_s2.z / gb_state.count;

    gb_state.mode = GB_READY;
    gb_output.mode = GB_READY;

    gb_output.bias_rad_s = gb_state.bias_rad_s;
    gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
} else {
    // Still collecting
    gb_output.variance_rad_s2.x = gb_state.m2_rad_s2.x / gb_state.count;
    gb_output.variance_rad_s2.y = gb_state.m2_rad_s2.y / gb_state.count;
    gb_output.variance_rad_s2.z = gb_state.m2_rad_s2.z / gb_state.count;
}
